module top_module (
	input [7:0] in,
	output reg [2:0] pos
);

	// The priority encoder should be combinational logic.
	// We check bits from least significant (0) to most significant (7).
	// The first bit that is '1' will determine the value of 'pos'.
	always @(*) begin
		if (in[0]) begin
			pos = 3'd0;
		end else if (in[1]) begin
			pos = 3'd1;
		end else if (in[2]) begin
			pos = 3'd2;
		end else if (in[3]) begin
			pos = 3'd3;
		end else if (in[4]) begin
			pos = 3'd4;
		end else if (in[5]) begin
			pos = 3'd5;
		end else if (in[6]) begin
			pos = 3'd6;
		end else if (in[7]) begin
			pos = 3'd7;
		end else begin
			// If no bits are high, report zero as per the description.
			pos = 3'd0;
		end
	end

endmodule
